import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Recreate the 5x5 framed panels; panel row/column 4 is cropped by the 30x30 boundary.
for ri,r0 in enumerate(starts):
  for ci,c0 in enumerate(starts):
    for dr in range(min(5,n-r0)):
      for dc in range(min(5,n-c0)):
        r,c=r0+dr,c0+dc
        if dr in (0,4) or dc in (0,4):
          g[r][c]=4
        elif ri<4 and ci<4:
          g[r][c]=colors[ri][ci]
# Connect only the non-background interior marker colors across zero separator corridors.
# Horizontal 3 connections in panel rows 0 and 2, across panel columns 0..3.
for r0 in (1,15):
  for rr in range(r0+1,r0+4):
    for c in (6,7,13,14,20,21): g[rr][c]=3
# Horizontal 8 connections in panel rows 1 and 3, between panel columns 1 and 2.
for r0 in (8,22):
  for rr in range(r0+1,r0+4):
    for c in (13,14): g[rr][c]=8
# Vertical 3 connections at outer panel columns, from panel row 0 through row 2.
for c0 in (1,22):
  for cc in range(c0+1,c0+4):
    for r in (6,7,13,14): g[r][cc]=3
# Vertical 8 connections in inner panel columns, from panel row 1 through row 3.
for c0 in (8,15):
  for cc in range(c0+1,c0+4):
    for r in (13,14,20,21): g[r][cc]=8
assert len(g)==30 and all(len(row)==30 and all(0<=x<=9 for x in row) for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
